package org.hlrcs.service;
import org.hlrcs.entity.*;
import org.hlrcs.entity.enums.*;
import org.hlrcs.entity.CommunityReportAnalysis.State;
import org.hlrcs.repository.*;
import org.junit.jupiter.api.DynamicTest;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.transaction.*;
import org.springframework.test.util.ReflectionTestUtils;
import java.time.LocalDateTime;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;

class CommunityReportAssistantMatrixTest extends CommunityUnitSupport {
    static class F implements AutoCloseable {
        CommunityReportAnalysisRepository jobs=mock(CommunityReportAnalysisRepository.class);ReportRepository reports=mock(ReportRepository.class);PostRepository posts=mock(PostRepository.class);PostMediaRepository media=mock(PostMediaRepository.class);CommunityReportEvidenceRepository evidence=mock(CommunityReportEvidenceRepository.class);GeminiCommunityScanner scanner=mock(GeminiCommunityScanner.class);AuthService auth=mock(AuthService.class);ApplicationEventPublisher events=mock(ApplicationEventPublisher.class);PlatformTransactionManager tx=mock(PlatformTransactionManager.class);
        CommunityReportAssistant s;Post p=post();User admin=user(2,UserRole.ADMIN);Report r=Report.builder().reportId(30).targetId(10).targetType(ReportTargetType.POST).status(ReportStatus.OPEN).reasonCode("INAPPROPRIATE").reason("allegation").reporter(user(3,UserRole.USER)).build();CommunityReportAnalysis j=CommunityReportAnalysis.builder().reportId(30).postId(10).state(State.QUEUED).generation(1).requestedAt(LocalDateTime.now().minusSeconds(120)).build();
        F(boolean enabled,boolean configured){p.setStatus(PostStatus.APPROVED);when(auth.getCurrentUser()).thenReturn(admin);when(scanner.configured()).thenReturn(configured);when(scanner.modelName()).thenReturn("test-model");when(tx.getTransaction(any())).thenReturn(mock(TransactionStatus.class));s=new CommunityReportAssistant(jobs,reports,posts,media,evidence,scanner,auth,JSON,events,tx,enabled,1000);
            when(reports.findByReportIdAndTargetType(30,ReportTargetType.POST)).thenReturn(Optional.of(r));when(reports.findTargetId(30,ReportTargetType.POST)).thenReturn(Optional.of(10));when(reports.findByTargetTypeAndTargetId(ReportTargetType.POST,10)).thenReturn(List.of(r));when(reports.lockForTarget(ReportTargetType.POST,10)).thenReturn(List.of(r));when(posts.findById(10)).thenReturn(Optional.of(p));when(posts.findForReview(10)).thenReturn(Optional.of(p));when(jobs.findByPostId(10)).thenReturn(List.of(j));when(jobs.lockById(30)).thenReturn(Optional.of(j));when(jobs.findById(30)).thenReturn(Optional.of(j));var entry=mock(CommunityReportAnalysisRepository.QueueId.class);when(entry.getReportId()).thenReturn(30);when(jobs.findFirstByStateOrderByRequestedAtAscReportIdAsc(State.QUEUED)).thenReturn(Optional.of(entry));
        }
        public void close(){s.stop();}
    }
    static tools.jackson.databind.JsonNode verdict(String assessment,String rule,String quote,String quote2,String reportQuote){return JSON.readTree(JSON.writeValueAsString(Map.of("assessment",assessment,"rule",rule,"explanation","Test finding","postQuote",quote,"postQuote2",quote2,"reportQuote",reportQuote)));}
    List<DynamicTest> assistantCases(){
        for(boolean enabled:List.of(false,true))for(boolean configured:List.of(false,true))for(boolean exists:List.of(false,true))add("CommunityReportAssistant.submitted","Normal","enabled="+enabled+", configured="+configured+", jobExists="+exists,"Idempotent job creation; QUEUED only when enabled/configured; otherwise DISABLED",()->{try(F f=new F(enabled,configured)){when(f.jobs.existsById(30)).thenReturn(exists);f.s.submitted(new CommunityReportSubmitted(30,10));verify(f.jobs,times(exists?0:1)).save(argThat(j->j.getReportId()==30&&j.getState()==(enabled&&configured?State.QUEUED:State.DISABLED)));}});
        for(String state:List.of("no-job","queued","ready-keep","ready-hide","ready-review","closed","deleted","hidden","stale","null-findings","failed"))add("CommunityReportAssistant.view","Normal","analysis="+state,"Resolve current analysis state and aggregate CLOSED/INCOMPLETE/KEEP/HIDE/ADMIN_REVIEW without changing reports",()->{
            try(F f=new F(true,true)){if(state.equals("no-job"))when(f.jobs.findByPostId(10)).thenReturn(List.of());if(state.startsWith("ready")){f.j.setState(State.READY);f.j.setRecommendation(state.equals("ready-hide")?"SUGGEST_HIDE":state.equals("ready-review")?"ADMIN_REVIEW":"SUGGEST_KEEP");f.j.setFingerprint(ReflectionTestUtils.invokeMethod(f.s,"fingerprint",f.p,f.r,List.of()));f.j.setFindings("[]");}if(state.equals("closed"))f.r.setStatus(ReportStatus.RESOLVED);if(state.equals("deleted"))when(f.posts.findById(10)).thenReturn(Optional.empty());if(state.equals("hidden"))f.p.setStatus(PostStatus.HIDDEN);if(state.equals("stale"))f.j.setFingerprint("outdated");if(state.equals("failed"))f.j.setState(State.FAILED);
                var v=f.s.view(30);assertEquals(1,v.items().size());String expected=state.equals("closed")?"CLOSED":state.equals("deleted")||state.equals("hidden")?"UNAVAILABLE":state.equals("no-job")?"NOT_ANALYZED":state.equals("stale")?"STALE":state.startsWith("ready")?"READY":state.equals("failed")?"FAILED":"QUEUED";assertEquals(expected,v.items().get(0).state());assertEquals(state.equals("closed")?"CLOSED":state.startsWith("ready")?f.j.getRecommendation():"INCOMPLETE",v.recommendation());verify(f.reports,never()).save(any());
            }
        });
        for(String method:List.of("view","request"))for(String error:List.of("inactive","non-admin","missing-report"))add("CommunityReportAssistant."+method,"Abnormal","failure="+error,"403 for forbidden account; 404 for missing selected report",()->{
            try(F f=new F(true,true)){if(error.equals("inactive"))f.admin.setStatus(UserStatus.INACTIVE);if(error.equals("non-admin"))f.admin.setRole(UserRole.USER);if(error.equals("missing-report")){when(f.reports.findByReportIdAndTargetType(30,ReportTargetType.POST)).thenReturn(Optional.empty());when(f.reports.findTargetId(30,ReportTargetType.POST)).thenReturn(Optional.empty());}status(error.equals("missing-report")?404:403,()->{if(method.equals("view"))f.s.view(30);else f.s.request(30);});}
        });
        for(String path:List.of("disabled","unconfigured","post-deleted","post-hidden","closed","running","queued","cooldown","new-job","retry"))add("CommunityReportAssistant.request","Normal","requestScenario="+path,"Reject unavailable/cooldown requests; queue open reports and reset prior analysis safely",()->{
            try(F f=new F(!path.equals("disabled"),!path.equals("unconfigured"))){f.j.setState(State.FAILED);if(path.equals("post-deleted"))when(f.posts.findForReview(10)).thenReturn(Optional.empty());if(path.equals("post-hidden"))f.p.setStatus(PostStatus.HIDDEN);if(path.equals("closed"))f.r.setStatus(ReportStatus.DISMISSED);if(path.equals("running"))f.j.setState(State.RUNNING);if(path.equals("queued"))f.j.setState(State.QUEUED);if(path.equals("cooldown"))f.j.setRequestedAt(LocalDateTime.now());if(path.equals("new-job"))when(f.jobs.lockById(30)).thenReturn(Optional.empty());
                if(Set.of("retry","new-job").contains(path)){assertNotNull(f.s.request(30));verify(f.jobs).save(argThat(j->j.getState()==State.QUEUED&&j.getFingerprint()==null&&j.getCompletedChecks()==0));verify(f.events).publishEvent(isA(CommunityRealtimeEvent.class));}else status(path.equals("disabled")||path.equals("unconfigured")?400:409,()->f.s.request(30));
            }
        });
        for(String path:List.of("disabled","unconfigured","empty-queue","missing-job","job-not-queued","no-target","post-deleted","post-hidden","report-missing","report-closed","clear","violation","provider-error","interrupted","fraud-uncertain","missing-media","with-evidence","stale-during-scan","generation-changed"))add("CommunityReportAssistant.runNext","Normal","workerScenario="+path,"Validate current job/report/post; record analysis and progress; never hide post or resolve report",()->{
            try(F f=new F(!path.equals("disabled"),!path.equals("unconfigured"))){when(f.scanner.assessReport(anyString(),any())).thenReturn(verdict("NO_VISIBLE_VIOLATION","NO_VISIBLE_VIOLATION","","",""));
                switch(path){case "empty-queue"->when(f.jobs.findFirstByStateOrderByRequestedAtAscReportIdAsc(State.QUEUED)).thenReturn(Optional.empty());case "missing-job"->when(f.jobs.lockById(30)).thenReturn(Optional.empty());case "job-not-queued"->f.j.setState(State.FAILED);case "no-target"->when(f.reports.findTargetId(30,ReportTargetType.POST)).thenReturn(Optional.empty());case "post-deleted"->when(f.posts.findForReview(10)).thenReturn(Optional.empty());case "post-hidden"->f.p.setStatus(PostStatus.HIDDEN);case "report-missing"->when(f.reports.lockForTarget(ReportTargetType.POST,10)).thenReturn(List.of());case "report-closed"->f.r.setStatus(ReportStatus.RESOLVED);case "violation"->when(f.scanner.assessReport(anyString(),any())).thenReturn(verdict("VIOLATION","EXPLICIT_SCAM","Community title","",""));case "provider-error"->when(f.scanner.assessReport(anyString(),any())).thenThrow(new java.io.IOException());case "interrupted"->when(f.scanner.assessReport(anyString(),any())).thenThrow(new InterruptedException());case "fraud-uncertain"->f.r.setReasonCode("FRAUD");case "missing-media"->when(f.media.findByPost_PostIdOrderByMediaIdAsc(10)).thenReturn(List.of(PostMedia.builder().mediaId(8).mediaType(org.hlrcs.entity.enums.MediaType.IMAGE).build()));case "with-evidence"->when(f.evidence.findById(30)).thenReturn(Optional.of(CommunityReportEvidence.builder().reportId(30).fileContent(new byte[]{1}).contentType("image/png").build()));case "stale-during-scan","generation-changed"->when(f.scanner.assessReport(anyString(),any())).thenAnswer(i->{if(path.equals("generation-changed"))f.j.setGeneration(2);else f.p.setDescription("Changed after claim");return verdict("NO_VISIBLE_VIOLATION","NO_VISIBLE_VIOLATION","","","");});}
                try{f.s.runNext();if(Set.of("clear","violation","fraud-uncertain","missing-media","with-evidence").contains(path)){assertEquals(State.READY,f.j.getState());assertEquals(path.equals("violation")?"SUGGEST_HIDE":path.equals("fraud-uncertain")||path.equals("missing-media")?"ADMIN_REVIEW":"SUGGEST_KEEP",f.j.getRecommendation());assertNotNull(f.j.getFinishedAt());}if(path.equals("provider-error")||path.equals("interrupted")){assertEquals(State.FAILED,f.j.getState());assertEquals("ADMIN_REVIEW",f.j.getRecommendation());}if(path.equals("stale-during-scan"))assertEquals(State.SKIPPED,f.j.getState());assertEquals(path.equals("post-hidden")?PostStatus.HIDDEN:PostStatus.APPROVED,f.p.getStatus());assertEquals(path.equals("report-closed")?ReportStatus.RESOLVED:ReportStatus.OPEN,f.r.getStatus());verify(f.reports,never()).save(any());}finally{Thread.interrupted();}
            }
        });
        for(String race:List.of("job-removed","job-not-running","post-removed","post-hidden","report-removed","report-closed","media-mime-missing","video","expired-job","pending-report","fraud-hide","attachment-stale"))add("CommunityReportAssistant.runNext","Abnormal","inFlightScenario="+race,"Check generation/current state before progress, attachment and final result; preserve moderator authority",()->{
            try(F f=new F(true,true)){if(race.equals("pending-report"))f.r.setStatus(ReportStatus.PENDING);if(race.equals("expired-job"))when(f.jobs.expire(any(),any(),any(),any())).thenReturn(1);if(race.equals("fraud-hide"))f.r.setReasonCode("FRAUD");
                if(Set.of("media-mime-missing","video","attachment-stale").contains(race))when(f.media.findByPost_PostIdOrderByMediaIdAsc(10)).thenReturn(List.of(PostMedia.builder().mediaId(8).mediaType(race.equals("video")?org.hlrcs.entity.enums.MediaType.VIDEO:org.hlrcs.entity.enums.MediaType.IMAGE).fileContent(new byte[]{1}).contentType(race.equals("media-mime-missing")?null:"video/mp4").build()));
                when(f.scanner.assessReport(anyString(),any())).thenAnswer(i->{switch(race){case "job-removed"->when(f.jobs.lockById(30)).thenReturn(Optional.empty());case "job-not-running"->f.j.setState(State.FAILED);case "post-removed"->when(f.posts.findForReview(10)).thenReturn(Optional.empty());case "post-hidden"->f.p.setStatus(PostStatus.HIDDEN);case "report-removed"->when(f.reports.lockForTarget(ReportTargetType.POST,10)).thenReturn(List.of());case "report-closed"->f.r.setStatus(ReportStatus.RESOLVED);case "attachment-stale"->f.p.setTitle("Changed while checking");}
                    return race.equals("fraud-hide")?verdict("VIOLATION","EXPLICIT_SCAM","Community title",""," ".strip()):verdict("NO_VISIBLE_VIOLATION","NO_VISIBLE_VIOLATION","","","");});
                f.s.runNext();if(Set.of("post-removed","post-hidden","report-removed","report-closed","attachment-stale").contains(race))assertEquals(State.SKIPPED,f.j.getState());else if(race.equals("job-not-running"))assertEquals(State.FAILED,f.j.getState());else if(!race.equals("job-removed")){assertEquals(State.READY,f.j.getState());assertEquals(race.equals("media-mime-missing")?"ADMIN_REVIEW":race.equals("fraud-hide")?"SUGGEST_HIDE":"SUGGEST_KEEP",f.j.getRecommendation());}
            }
        });
        return cases;
    }
}
